        visited[r][c] = True
        while stack:
            curr_r, curr_c = stack.pop()
            cells.append((curr_r, curr_c))
            for dr, dc in directions:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == foreground and not visited[nr][nc]:
                        visited[nr][nc] = True
                        stack.append((nr, nc))
        return cells

    # Find all connected components
    components = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == foreground and not visited[r][c]:
                cells = get_component(r, c)
                # Count unique rows and columns in this component
                rows_set = set(cell[0] for cell in cells)
                cols_set = set(cell[1] for cell in cells)
                is_horizontal = len(rows_set) == 1
                is_vertical = len(cols_set) == 1
                size = len(cells)
                components.append({
                    'cells': cells,
                    'is_horizontal': is_horizontal,
                    'is_vertical': is_vertical,
                    'size': size
                })

    # Apply transformation rules
    output = [[0] * cols for _ in range(rows)]
    for comp in components:
        size = comp['size']
        is_horiz = comp['is_horizontal']
        is_vert = comp['is_vertical']

        if is_vert and size >= 2:
            val = 2  # Vertical line
        elif is_horiz:
            if size >= 3:
                val = 1  # Horizontal line of 3+
            else:  # size == 2
                val = 3  # Horizontal line of 2
        else:
            val = 3  # Non-linear shapes, L-shapes, single cells

        for cr, cc in comp['cells']:
            output[cr][cc] = val

    return output
