Let me implement with proper component analysis:

```python
def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])
    background = grid[0][0]

    foreground = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                foreground = grid[r][c]
                break
        if foreground:
            break

    if not foreground:
        return grid

    visited = [[False] * cols for _ in range(rows)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_component(r, c):
        cells = []
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            curr_r, curr_c = stack.pop()
            cells.append((curr_r, curr_c))
            for dr, dc in directions:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == foreground and not visited[nr][nc]:
                        visited[nr][nc] = True
                        stack.append((nr, nc))
        return cells

    # Collect all components first
    components = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == foreground and not visited[r][c]:
                cells = get_component(r, c)
                rows_set = set(x[0] for x in cells)
                cols_set = set(x[1] for x in cells)
                size = len(cells)
                components.append({'cells': cells, 'size': size, 'rows': rows_set, 'cols': cols_set})

    output = [[0] * cols for _ in range(rows)]

    for comp in components:
        cells = comp['cells']
        rows_set = comp['rows']
        cols_set = comp['cols']
        size = comp['size']

        # Check if pure horizontal or pure vertical
        is_horizontal = len(rows_set) == 1
        is_vertical = len(cols_set) == 1

        if is_vertical:
            val = 2 if size >= 2 else 3
        elif is_horizontal:
            val = 1 if size >= 3 else 3
        else:
            # Non-linear or mixed
            val = 3

        for r, c in cells:
            output[r][c] = val

    return output
